{"meetingId": "268", "tickets": [
{"title": "Compare charitable funding source options", "text": "Compare donating appreciated Moonbadger Systems shares, donating cash from the taxable account, and using a donor-advised fund for Jasper Lanternmoss's planned ~$150,000 charitable commitment, including effects on portfolio concentration and estimated taxable gains avoided on the ~$480,000 Moonbadger Systems position (cost basis ~$92,000) at Velvet Acorn Custody.", "priority": null, "dueDate": "2026-08-06", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "For the charitable funding source comparison, Jasper asked about donating appreciated Moonbadger Systems shares, donating cash from the taxable account, and using a donor-advised fund, including effects on portfolio concentration and estimated taxable gains avoided; the agreed follow-up is due 2026-08-06."},
{"title": "Obtain Pocket Lantern Youth Lab delivery instructions", "text": "Obtain from Pocket Lantern Youth Lab the full securities delivery instructions, legal name, tax identification confirmation, and gift-acceptance contact needed to move appreciated securities cleanly; the nonprofit has so far provided only a general development-office email and a brokerage name.", "priority": null, "dueDate": "2026-08-13", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "Jasper has not received the full delivery instructions, legal name, tax identification confirmation, or gift-acceptance contact needed to move securities cleanly; follow-up is needed for 2026-08-13."},
{"title": "Resolve donor-advised fund registration mismatch", "text": "Resolve the registration mismatch between the draft donor-advised fund paperwork, which lists Jasper Lanternmoss individually, and the Velvet Acorn Custody taxable account titled jointly with Lena Lanternmoss, confirming required authorization and acknowledgement naming before any securities delivery.", "priority": null, "dueDate": "2026-08-12", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the draft donor-advised fund paperwork lists Jasper individually while the Velvet Acorn Custody taxable account is titled jointly with Lena, creating uncertainty about required authorization and acknowledgement naming; follow-up is needed for 2026-08-12."},
{"title": "Confirm securities gift delivery and notification steps", "text": "Confirm current delivery instructions and notification steps with Velvet Acorn Custody before initiating another securities gift for Jasper Lanternmoss, since a prior gift took nearly three weeks and the charity initially could not identify the donor.", "priority": null, "dueDate": "2026-08-16", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "a prior securities gift through Velvet Acorn Custody took nearly three weeks and the charity initially could not identify the donor, so the agreed follow-up due 2026-08-16 is to confirm current delivery instructions and notification steps before initiating another gift."},
{"title": "Identify tax lots for charitable share donation", "text": "Identify the specific Moonbadger Systems shares selected for donation before preparing any transfer request, since the position at Velvet Acorn Custody includes several high-gain lots and a few recent reinvestment lots.", "priority": null, "dueDate": "2026-08-09", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the Moonbadger Systems position includes several high-gain lots and a few recent reinvestment lots, so the agreed tax-lot follow-up due 2026-08-09 is to identify the specific shares selected for donation before any transfer request is prepared."},
{"title": "Set initial gift and later grant timing", "text": "Set timing for Jasper Lanternmoss's initial gift to Pocket Lantern Youth Lab before the family's campaign update, while preserving flexibility for later grants to the food security and arts organizations within the ~$150,000 total charitable commitment.", "priority": null, "dueDate": "2026-08-20", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "he wants an initial gift to Pocket Lantern Youth Lab before the family's campaign update, while leaving flexibility for later grants to the food security and arts organizations; the agreed grant-timing follow-up is due 2026-08-20."},
{"title": "Assemble charitable documentation packet", "text": "Assemble the documentation packet for Jasper and Lena Lanternmoss's noncash charitable gifts, including nonprofit receipt requirements, account transfer confirmations, and the year-end reporting file, supporting Rowan Copperwisp, CPA's request for contemporaneous acknowledgements and valuation support.", "priority": null, "dueDate": "2026-12-15", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the household has not yet assembled the nonprofit receipt requirements, account transfer confirmations, and year-end reporting file; follow-up on the documentation packet is needed for 2026-12-15."}
]}
